# If none of the items are expanded (or all being displayed), send message to toggle the expand/collapse button
if currentValue.value["expanded"].value == 0 or currentValue.value["displayed"].value == currentValue.value["expanded"].value:
	payload = {"allExpanded": bool(currentValue.value["expanded"].value), "uuid": self.params.uuid}
	system.perspective.sendMessage("toggleExpandCollapseAll", payload)

