# Verify UUID matches
if payload["uuid"] == self.view.params.uuid:
	if payload["source"] in ("IA", "CL", "SS", "TPM", "computing", "gatewayConfig", "support"):
		# Toggle expansion of module vendor
		self.view.params.visibility.expanded[payload["source"]] = payload["value"]
	elif payload["source"] == "all":
		# Toggle expansion of all entries
		for entry in self.view.params.visibility.expanded:
			self.view.params.visibility.expanded[entry] = payload["value"]
